# dedupe_preserve_order :: [1, 2, 2, 3, 1, 4]
def dedupe_preserve_order(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

if __name__ == "__main__":
    print(dedupe_preserve_order([1, 2, 2, 3, 1, 4]))

